  -epub-line-break: normal;
  -webkit-line-break: normal;
}
{% endif %}

div.clearer {
    clear: both;
}

a:link {
    color: #3333ff;
    text-decoration: underline;
}

a:visited {
    color: #551a8b;
    text-decoration: underline;
} 

img {
    border: 0;
    max-width: 100%;
}

/* -- relbar ---------------------------------------------------------------- */

div.related {
    width: 100%;
    font-family: sans-serif;
    font-size: 90%;
}

div.related h3 {
    display: none;
